/* --- Primer parcial · Ejercicio 2b y 2c: semántica y equivalencias --- */
lgEx("1P26 · Ej. 2bc (semántica)","lg2",LGI.sem,["Primer parcial de Lógica, 28 de abril de 2026 · Ejercicio 2 (10 puntos)","Considere tres fórmulas α, β y φ de PROP.",
 "b. Demuestre que si β ⊨ φ, y α eq β ∧ φ, entonces α eq β","c. Demuestre mediante equivalencias que las siguientes fórmulas son equivalentes: (α → β) ∧ ¬β y ¬(β ∨ α)"],[
 {id:"b1",k:"seq",t:"b) cómo empieza la prueba",ex:"Por qué «sea v una valuación genérica»: la tesis α eq β dice v(α) = v(β) para TODA valuación v. Para probar un «para toda v» no se revisan las valuaciones una por una (son infinitas): se toma una v cualquiera, sin suponer nada de ella (genérica), y se prueba para esa. Como no se usó nada especial de v, vale para todas. Las hipótesis H1 y H2 también se aplican a esa misma v.",p:"Paso 1: H1) β ⊨ φ · H2) α eq β ∧ φ · T) α eq β. ¿Cómo arrancás y qué dice H1?",sl:["Sea",["v una valuación genérica","H1, H2 y la tesis hablan de toda valuación.","el comienzo",["v una valuación con v(β) = 1","Hay que probar v(α) = v(β) para TODA v, también cuando v(β) = 0."]],"\n","H1) β ⊨ φ quiere decir: para esa v,",
   ["si v(β) = 1, entonces v(φ) = 1","⊨ va en una sola dirección: cuando β vale 1, φ también.","qué dice H1",["v(β) = v(φ)","⊨ no es igualdad: si v(β) = 0, v(φ) puede valer 0 o 1."],["si v(φ) = 1, entonces v(β) = 1","Es al revés: β ⊨ φ dice que β verdadera obliga a φ verdadera."]]]},
 {id:"b1c",k:"seq",t:"b) lo que sale de H1",p:"Paso 2: H2 tiene v(β ∧ φ) = mín{v(β), v(φ)}. Usando H1 («de H1 sale» = «usando H1, se obtiene»), ¿cuánto vale ese mínimo? Mirá los dos casos de v(β).",mo:1,sl:["si v(β) = 1:",["por H1 v(φ) = 1, y mín{1, 1} = 1 = v(β)","Se usa H1.","el caso 1",["v(φ) puede valer 0, y mín = 0","H1 obliga a v(φ) = 1 cuando v(β) = 1."]],"\n","si v(β) = 0:",
   ["mín{0, v(φ)} = 0 = v(β), valga lo que valga v(φ)","El mínimo con un 0 es 0.","el caso 0",["mín{0, v(φ)} = v(φ)","Si v(φ) = 1, mín{0, 1} = 0 ≠ v(φ)."]],"\n","en los dos casos:",
   ["v(β) = mín{v(β), v(φ)}   (A)","Es lo que se usa en la cadena.","lo que sale de H1",["v(β) = v(φ)","β ⊨ φ no da igualdad: si v(β) = 0, v(φ) puede valer 1."],["v(φ) = mín{v(β), v(φ)}","Si v(β) = 0 y v(φ) = 1, el mínimo es 0 ≠ v(φ)."]]]},
 {id:"b2",k:"cad",t:"b) la cadena desde H2",p:"Con (A), llevá H2 hasta la tesis.",mo:1,ini:"α eq β ∧ φ",st:["⇔ (def. eq)   v(α) = v(β ∧ φ)","⇔ (def. valuación)   v(α) = mín{v(β), v(φ)}","⇔ ((A))   v(α) = v(β)","⇔ (v genérica y def. eq)   α eq β"],
  no:[["⇔ (def. valuación)   v(α) = máx{v(β), v(φ)}","máx es la valuación de ∨; la de ∧ es mín."],["⇔ ((A))   v(α) = v(φ)","(A) dice que el mínimo vale v(β), no v(φ)."]]},
 {id:"c",k:"cad",t:"c) cadena de equivalencias",p:"Llevá (α → β) ∧ ¬β hasta ¬(β ∨ α). La conmutativa se puede usar en cualquier momento; acá se deja para el final.",mo:1,ini:"(α → β) ∧ ¬β",st:["eq (equivalencia →)   (¬α ∨ β) ∧ ¬β","eq (distributiva)   (¬α ∧ ¬β) ∨ (β ∧ ¬β)","eq (bottom)   (¬α ∧ ¬β) ∨ ⊥","eq (neutro)   ¬α ∧ ¬β","eq (De Morgan)   ¬(α ∨ β)","eq (conmutativa)   ¬(β ∨ α)"],
  no:[["eq (equivalencia →)   (α ∨ ¬β) ∧ ¬β","α → β eq ¬α ∨ β: se niega el antecedente."],["eq (distributiva)   (¬α ∨ ¬β) ∧ (β ∨ ¬β)","Esa distribuye ∨ sobre ∧. Acá hay (… ∨ …) ∧ ¬β: se distribuye el ∧."],["eq (De Morgan)   ¬(α ∧ β)","De Morgan cambia el conectivo: ¬α ∧ ¬β eq ¬(α ∨ β)."]]}]);

/* --- Primer parcial · Ejercicio 4: completo, consistente y maximal --- */
lgEx("1P26 · Ej. 4 (consistencia)","lg4",LGI.con,["Primer parcial de Lógica, 28 de abril de 2026 · Ejercicio 4 (10 puntos)","Demuestre las siguientes afirmaciones:",
 "a. Existe un conjunto Γ1 ⊆ PROP completo tal que el conjunto ∆1 = {¬φ | φ ∈ Γ1} es consistente.","b. Existe un conjunto Γ2 ⊆ PROP consistente tal que el conjunto ∆2 = {¬φ | φ ∈ Γ2} es inconsistente.",
 "c. Para cualquier Γ3 ⊆ PROP, si Γ3 es consistente maximal, entonces ∆3 = {¬φ | φ ∈ Γ3} no es consistente maximal.","Se recuerda que un conjunto ∆ ⊆ PROP es completo si y solo si: ∆ es consistente y para todo φ ∈ PROP se cumple: ∆ ⊢ φ o ∆ ⊢ ¬φ."],[
 {id:"a",k:"seq",t:"a) Γ1 completo con ∆1 consistente",p:"Antes de buscar Γ1: traducí cada condición a valuaciones.",sl:["Γ1 completo ⇔",["existe una única valuación v que satisface a Γ1","Caracterización semántica de la completitud (práctico 5).","qué pide completo",["toda valuación satisface a Γ1","Eso es que sus fórmulas sean tautologías. Completo pide que la valuación quede determinada: una sola."],["para toda φ: φ ∈ Γ1 o ¬φ ∈ Γ1","Eso es de un consistente maximal. Completo habla de lo que se deriva (⊢), no de lo que pertenece."]],"\n","∆1 consistente ⇔ hay una valuación w con",
   ["w(φ) = 0 para toda φ ∈ Γ1","w(¬φ) = 1 − w(φ): satisfacer cada ¬φ es hacer falsa cada φ, todas en la misma w.","qué pide ∆1",["w(φ) = 1 para toda φ ∈ Γ1","Eso dice que Γ1 es consistente. ∆1 tiene las NEGACIONES: cada φ de Γ1 tiene que ser falsa en w."],["w(φ) = 0 para alguna φ ∈ Γ1","w tiene que satisfacer TODAS las fórmulas de ∆1: todas las φ de Γ1 falsas a la vez."]]]},
 {id:"a2",k:"seq",t:"a) qué tiene que cumplir Γ1",p:"Con lo anterior, ¿qué condiciones tiene que cumplir Γ1?",mo:1,sl:["para que haya una sola v, Γ1 tiene que",["fijar el valor de cada letra proposicional","Una valuación queda determinada por los valores de las letras: si una queda libre, hay dos valuaciones.","la primera condición",["fijar el valor de alguna letra","Las otras letras quedan libres: muchas valuaciones lo satisfacen."],["ser consistente","Hace falta, pero no alcanza: {p0} es consistente y lo satisfacen infinitas valuaciones."]],"\n","para que exista w, Γ1 no puede tener",
   ["tautologías (como ¬⊥)","Una tautología SÍ es consistente (¬⊥ vale siempre). El problema es ∆1: su negación (¬¬⊥) vale 0 en toda valuación, así que ninguna w satisface a ∆1.","la segunda condición",["letras proposicionales","Una letra sí se puede hacer 0: alcanza con w(pi) = 0."],["fórmulas con ¬","¬p0 se hace 0 con w(p0) = 1. El problema son las fórmulas que valen 1 en TODA valuación."]]]},
 {id:"a3",k:"seq",t:"a) elegir Γ1",p:"Elegí un Γ1 que cumpla las dos condiciones.",mo:1,sl:["Γ1 :=",["P (todas las letras proposicionales)","Fija cada letra en 1 (v(pi) = 1) y no tiene tautologías: cada pi se puede hacer 0. También serviría {¬pi | pi ∈ P}.","el conjunto",
   ["{φ ∈ PROP | v(φ) = 1}, con v(pi) = 1 para toda i","Es completo, pero tiene a ¬⊥ (tautología): ¬¬⊥ ∈ ∆1 y ∆1 deriva ⊥."],["{p0}","Solo fija p0: p1 queda libre, lo satisfacen muchas valuaciones y no es completo."],["{¬⊥}","¬⊥ es una tautología y no fija ninguna letra: falla las dos condiciones."]]]},
 {id:"a4",k:"seq",t:"a) la justificación",p:"Con Γ1 = P, justificá las dos afirmaciones.",mo:1,sl:["Γ1 es completo porque",
   ["la única valuación que lo satisface es v, con v(pi) = 1 para toda i","Cada pi ∈ Γ1 obliga a v(pi) = 1. Caracterización semántica de la completitud.","por qué es completo",["es consistente","Consistente no alcanza: completo pide además Γ ⊢ φ o Γ ⊢ ¬φ para toda φ."]],"\n","∆1 = {¬pi | pi ∈ P} es consistente porque",
   ["w, con w(pi) = 0 para toda i, lo satisface","w(¬pi) = 1 − 0 = 1 para cada i: condición suficiente de consistencia.","por qué ∆1 es consistente",["Γ1 es completo","Eso no dice nada de las negaciones: hay que dar una valuación que satisfaga a ∆1."],["v, con v(pi) = 1 para toda i, lo satisface","v(¬pi) = 0: v satisface a Γ1, no a ∆1."]]]},
 {id:"b",k:"seq",t:"b) Γ2 consistente con ∆2 inconsistente",p:"Paso 1: ¿qué tiene que tener Γ2 para que ∆2 sea inconsistente?",mo:1,sl:["∆2 inconsistente ⇔",["∆2 ⊢ ⊥","Definición.","la definición",["∆2 ⊬ ⊥","Eso es consistente."]],"\n","∆2 tiene las negaciones, así que busco φ ∈ Γ2 con",
   ["¬φ contradicción, o sea φ tautología","Si φ vale siempre 1, ¬φ vale siempre 0 y deriva ⊥.","la condición",["φ contradicción","Γ2 tiene que ser consistente: no puede tener una contradicción."],["φ letra proposicional","¬p0 se satisface con v(p0) = 0."]]]},
 {id:"b2",k:"seq",t:"b) elegir Γ2 y justificar",p:"Paso 2: elegí Γ2 (la tautología típica) y justificá.",mo:1,sl:["Γ2 :=",["{¬⊥}","Es consistente (¬⊥ vale siempre) y ∆2 = {¬¬⊥} deriva ⊥.","el conjunto",["{⊥}","Γ2 tiene que ser consistente, y {⊥} no lo es."],["{p0}","∆2 = {¬p0} es consistente: la valuación con v(p0) = 0 lo satisface."]],"\n","∆2 es inconsistente porque",
   ["¬¬⊥ ⊢ ⊥: suponiendo [⊥]¹, I¬ da ¬⊥, y E¬ con ¬¬⊥ da ⊥","Una derivación de ⊥ con hipótesis en ∆2.","el argumento",["¬¬⊥ es una tautología","v(¬¬⊥) = v(⊥) = 0: es una contradicción."]]]},
 {id:"c1",k:"seq",t:"c) la idea",p:"Sea Γ3 consistente maximal arbitrario. ¿Qué fórmula de Γ3 usás?",mo:1,sl:["en Γ3 está",["¬⊥, porque un consistente maximal contiene a todos los teoremas","Su negación ¬¬⊥ deriva ⊥ (parte b).","la fórmula",["⊥","Un conjunto consistente no contiene a ⊥."],["p0","No todo consistente maximal tiene a p0: puede tener a ¬p0."]]]},
 {id:"c2",k:"cad",t:"c) la cadena",p:"Desde ¬⊥ ∈ Γ3, llegá a que ∆3 no es consistente maximal.",mo:1,ini:"¬⊥ ∈ Γ3",st:["⇒ (teoría de conjuntos)   ¬¬⊥ ∈ {¬φ | φ ∈ Γ3}","⇒ (def. ∆3)   ¬¬⊥ ∈ ∆3","⇒ (derivación de la parte b)   ∆3 ⊢ ⊥","⇒ (def. consistente)   ∆3 es inconsistente, así que no es consistente maximal"],
  no:[["⇒ (def. ∆3)   ¬⊥ ∈ ∆3","∆3 tiene las negaciones de las fórmulas de Γ3: de ¬⊥ sale ¬¬⊥."],["⇒ (derivación de la parte b)   ∆3 ⊬ ⊥","La parte b derivó ⊥ desde ¬¬⊥: ∆3 ⊢ ⊥."]]}]);

/* --- Segundo parcial, 10/7/2026 · Ejercicio 1: términos cerrados e inducción --- */
lgEx("2P26 · Ej. 1 (inducción)","lg1",LGI.ind,["Segundo parcial de Lógica, 10 de julio de 2026 · Ejercicio 1 (15 puntos)","Sea un lenguaje de primer orden con igualdad de tipo de similaridad ⟨−; 1, 2; 1⟩ con símbolos de funciones f y g y símbolo de constante c.",
 "a. Defina TERMC, el conjunto de términos cerrados del lenguaje.","b. Defina una función siguiendo el ERP para TERMC: Cambiar : TERMC → TERMC que convierte todas las ocurrencias de f por g, duplicando el parámetro. Por ejemplo: Cambiar(f(c)) = g(c, c) · Cambiar(g(c, f(c))) = g(c, g(c, c)) · Cambiar(f(g(c, c))) = g(g(c, c), g(c, c)) · Cambiar(f(f(c))) = g(g(c, c), g(c, c))",
 "c. Sea la estructura M = ⟨N, ∗2, +, 1⟩, donde la función ∗2 retorna el resultado de multiplicar un natural por 2. Demuestre por inducción que: (∀t ∈ TERMC)(t^M = Cambiar(t)^M)"],[
 {id:"a",k:"set",t:"a) el conjunto TERMC",p:"¿Qué cláusulas definen a TERMC?",ok:[["(i) c ∈ TERMC","Base: la constante."],["(ii) Si t ∈ TERMC, entonces f(t) ∈ TERMC","f es unaria (el 1 del tipo)."],["(iii) Si t1, t2 ∈ TERMC, entonces g(t1, t2) ∈ TERMC","g es binaria (el 2 del tipo)."]],
  no:[["(i) Si x es una variable, x ∈ TERMC","Los términos CERRADOS no tienen variables: la base es solo c."],["(iii) Si t ∈ TERMC, entonces g(t) ∈ TERMC","El tipo ⟨−; 1, 2; 1⟩ dice que g lleva dos argumentos."],["(ii) Si t ∈ TERMC, entonces f(t, t) ∈ TERMC","f es unaria; el que duplica el parámetro es Cambiar, en la parte b."]]},
 {id:"b",k:"set",t:"b) la función Cambiar",p:"¿Cómo se define Cambiar, con un caso por cláusula de TERMC?",ok:[["Cambiar(c) = c","No hay f que cambiar."],["Cambiar(f(t)) = g(Cambiar(t), Cambiar(t))","f pasa a g con el parámetro duplicado, y se sigue cambiando adentro."],["Cambiar(g(t1, t2)) = g(Cambiar(t1), Cambiar(t2))","g se conserva; se cambia adentro."]],
  no:[["Cambiar(f(t)) = g(t, t)","Adentro de t puede haber más f: mirá Cambiar(f(f(c))) = g(g(c, c), g(c, c))."],["Cambiar(g(t1, t2)) = g(t1, t2)","Adentro puede haber f: Cambiar(g(c, f(c))) = g(c, g(c, c))."],["Cambiar(f(t)) = f(Cambiar(t))","Hay que sacar la f: va g con el parámetro duplicado."]]},
 {id:"c1",k:"set",t:"c) plan de la prueba",p:"¿Cómo se plantea la prueba por inducción?",mo:1,ok:[["Propiedad: P(t) := t^M = Cambiar(t)^M","PIP para TERMC."],["Paso base: P(c)",""],["Paso inductivo de f: HI P(t), TI P(f(t))",""],["Paso inductivo de g: HI P(t1) y P(t2), TI P(g(t1, t2))","Dos argumentos: una HI para cada uno."]],
  no:[["Paso inductivo de g: HI P(t1), TI P(g(t1, t2))","g arma el término con dos partes: hace falta la HI para las dos."],["Paso base: P(x) para cada variable x","Los términos cerrados no tienen variables."],["Inducción sobre N","La propiedad es (∀t ∈ TERMC): el PIP es el de TERMC, aunque el universo de M sea N."]]},
 {id:"c2",k:"seq",t:"c) paso base",p:"Probá P(c): c^M = Cambiar(c)^M.",mo:1,sl:["se cumple porque",["Cambiar(c) = c por def. de Cambiar, así que Cambiar(c)^M = c^M","Sale directo de la definición.","el argumento",["c^M = Cambiar(c)^M por HI","En el paso base no hay hipótesis inductiva."],["c^M = 1 y Cambiar(c)^M = 2","Cambiar(c) = c: no cambia nada, y los dos se interpretan como 1."]]]},
 {id:"c3",k:"cad",t:"c) paso inductivo de f",p:"Con la HI t^M = Cambiar(t)^M, probá Cambiar(f(t))^M = f(t)^M.",mo:1,ini:"Cambiar(f(t))^M",st:["= (def. Cambiar)   g(Cambiar(t), Cambiar(t))^M","= (def. M e interpretación de g)   Cambiar(t)^M + Cambiar(t)^M","= (HI)   t^M + t^M","= (aritmética)   2 ∗ t^M","= (def. M e interpretación de f)   f(t)^M"],
  no:[["= (def. M e interpretación de g)   Cambiar(t)^M ∗ Cambiar(t)^M","En M = ⟨N, ∗2, +, 1⟩ las funciones van en el orden del tipo: f es ∗2 y g es +."],["= (def. Cambiar)   g(t, t)^M","Cambiar(f(t)) = g(Cambiar(t), Cambiar(t)): se sigue cambiando adentro."],["= (HI)   f(t)^M","La HI habla de t, no de f(t): usarla así es suponer la tesis."]]},
 {id:"c4",k:"cad",t:"c) paso inductivo de g",p:"Con las HI t1^M = Cambiar(t1)^M y t2^M = Cambiar(t2)^M, probá Cambiar(g(t1, t2))^M = g(t1, t2)^M.",mo:1,ini:"Cambiar(g(t1, t2))^M",st:["= (def. Cambiar)   g(Cambiar(t1), Cambiar(t2))^M","= (def. M e interpretación de g)   Cambiar(t1)^M + Cambiar(t2)^M","= (HI1 y HI2)   t1^M + t2^M","= (def. M e interpretación de g)   g(t1, t2)^M"],
  no:[["= (def. M e interpretación de g)   2 ∗ Cambiar(t1)^M","∗2 es la interpretación de f; g es la suma de sus dos argumentos."],["= (HI1 y HI2)   g(t1, t2)^M","Las HI hablan de t1 y t2: primero hay que interpretar g para que aparezcan sus valores."]]}]);

/* --- Segundo parcial · Ejercicio 2: estructuras con igualdad --- */
lgEx("2P26 · Ej. 2 (modelos)","lg4",LGI.mod,["Segundo parcial de Lógica, 10 de julio de 2026 · Ejercicio 2 (15 puntos)","Considere un lenguaje de primer orden con igualdad, con tipo de similaridad ⟨−; −; 0⟩. Sean las siguientes definiciones:",
 "α := (∀x)(∀y)(∀z)(x =′ y ∨ x =′ z ∨ y =′ z)    β := (∃x)(∃y)(¬x =′ y)","a. Dé dos estructuras M1, M2 con universos de cardinalidad distinta que modelen α.","b. Dé una estructura Mb tal que Mb ⊨ α y Mb ⊭ β.","c. Dé una fórmula φ ∈ FORM tal que Mc ⊨ φ y ⊭ φ, donde Mc = ⟨{◦, □, △}⟩."],[
 {id:"A",k:"cad",t:"qué cumple un modelo de α",th:"Para abrir M ⊨ fórmula: 2.4.5 dice M ⊨ (∀x)φ ⇔ para todo a ∈ U, M ⊨ φ[ā/x] (se cambia x por el nombre ā de cada elemento); con tres ∀ seguidos quedan «para todo a, b, c ∈ U». Después: M ⊨ (A ∨ B) ⇔ M ⊨ A o M ⊨ B; y M ⊨ ā =′ b̄ ⇔ a = b (los dos son el mismo elemento). Lo practicaste en «Ejemplos típicos 1».",p:"Sea M = ⟨U⟩ genérica. Abrí M ⊨ α hasta una condición sobre U.",ini:"M ⊨ (∀x)(∀y)(∀z)(x =′ y ∨ x =′ z ∨ y =′ z)",st:["⇔ (2.4.5 y sust.)   (∀a, b, c ∈ U) M ⊨ (ā =′ b̄ ∨ ā =′ c̄ ∨ b̄ =′ c̄)","⇔ (2.4.5)   (∀a, b, c ∈ U)(M ⊨ ā =′ b̄ o M ⊨ ā =′ c̄ o M ⊨ b̄ =′ c̄)","⇔ (def. ⊨)   (∀a, b, c ∈ U)(v^M(ā =′ b̄) = 1 o v^M(ā =′ c̄) = 1 o v^M(b̄ =′ c̄) = 1)","⇔ (def. v^M)   (∀a, b, c ∈ U)(a = b o a = c o b = c)   (A)"],
  no:[["⇔ (2.4.5 y sust.)   (∃a, b, c ∈ U) M ⊨ (ā =′ b̄ ∨ ā =′ c̄ ∨ b̄ =′ c̄)","Un ∀ de la fórmula pasa a «para todo elemento del universo»."],["⇔ (2.4.5)   (∀a, b, c ∈ U)(M ⊨ ā =′ b̄ y M ⊨ ā =′ c̄ y M ⊨ b̄ =′ c̄)","El ∨ pasa a «o», no a «y»."]]},
 {id:"A2",k:"seq",t:"(A) en palabras",p:"Decí en palabras qué exige (A) al universo.",mo:1,sl:["(A) dice que",["el universo tiene a lo sumo 2 elementos","Entre tres elementos cualesquiera dos coinciden: no caben tres distintos.","qué dice la fórmula",["el universo tiene exactamente 3 elementos","Es al revés: (A) dice que NO hay tres distintos."],["el universo tiene un solo elemento","Con dos también se cumple: entre a, b y c alguno se repite."],["todos los elementos son iguales entre sí","Eso sería (∀x)(∀y) x =′ y; (A) deja que haya dos distintos."]]]},
 {id:"B",k:"seq",t:"qué cumple un modelo de β",p:"Abrí M ⊨ β de la misma forma.",mo:1,sl:["M ⊨ β ⇔",["(∃a ∈ U)(∃b ∈ U) a ≠ b   (B)","M ⊨ ¬ā =′ b̄ es M ⊭ ā =′ b̄, o sea v^M(ā =′ b̄) = 0.","la condición",["(∀a ∈ U)(∀b ∈ U) a ≠ b","El ∃ de la fórmula pasa a «existe un elemento», no a «todos»."],["(∃a ∈ U)(∃b ∈ U) a = b","β tiene ¬x =′ y: hace falta un par de elementos distintos."]],"\n","en palabras:",
   ["hay al menos 2 elementos distintos","Un par distinto alcanza; puede haber más.","qué dice la fórmula",["todos los elementos son distintos","Eso pide un ∀; (B) es un ∃: alcanza un par."],["hay exactamente 2 elementos","(B) no pone tope: con tres también vale."]]]},
 {id:"a",k:"est",t:"a) dos modelos de α",p:"El tipo ⟨−; −; 0⟩ no tiene predicados, funciones ni constantes: armá solo los universos.",mo:1,ms:[{nm:"M1",tp:[["U","U1"]]},{nm:"M2",tp:[["U","U2"]]}],sl:[
   ["{◦}","Un solo elemento: a = b = c siempre, se cumple (A). Es el modelo trivial de «a lo sumo».","U1",["∅","El universo de una estructura no puede ser vacío."]],
   ["{◦, □}","Dos elementos: entre a, b y c dos se repiten. Distinta cardinalidad que M1.","U2",["{◦, □, △}","Con a = ◦, b = □, c = △ falla (A): son tres distintos."],["N (los naturales)","Tiene tres distintos (0, 1, 2): falla (A)."]],"\n","porque",
   ["en un universo de uno o dos elementos, entre a, b y c alguno se repite: se cumple (A)","Es la condición (A).","el argumento",["los universos tienen cardinalidad distinta","Eso lo pide la letra, pero no prueba que modelen α."]]]},
 {id:"b",k:"seq",t:"b) Mb ⊨ α y Mb ⊭ β",p:"Paso 1: juntá las dos condiciones en palabras.",mo:1,sl:["Mb ⊨ α:",["a lo sumo 2 elementos (A)","Lo leíste antes.","α",["al menos 2 distintos","Eso es (B)."]],"\n","Mb ⊭ β:",
   ["no hay dos elementos distintos","Negar «al menos 2 distintos».","no β",["hay a lo sumo 2 elementos","Eso es α; negar β dice que no hay ni un par distinto."]],"\n","así que Mb tiene",
   ["exactamente un elemento","El universo no es vacío y no hay dos distintos.","cuántos",["dos elementos","Dos elementos son distintos: valdría β."]]]},
 {id:"b2",k:"est",t:"b) armar Mb",p:"Paso 2: armá Mb y justificá.",mo:1,ms:[{nm:"Mb",tp:[["U","U"]]}],sl:[["{◦}","Un solo elemento: el de M1 (parte a).","U",["{◦, □}","◦ ≠ □: Mb ⊨ β."]],"\n","Mb ⊭ β porque",
   ["por (B) habría que tener a ≠ b en {◦}, o sea ◦ ≠ ◦, que es falso","Un universo unitario no tiene dos elementos distintos.","el argumento",["Mb no modela α","Sí lo modela (parte a): lo que falla es β."]]]},
 {id:"c",k:"seq",t:"c) Mc ⊨ φ y ⊭ φ",p:"Paso 1: ¿qué pide cada mitad?",mo:1,sl:["⊭ φ ⇔",["existe una estructura donde φ falla","φ no es válida.","⊭ φ",["φ falla en toda estructura","Eso sería ⊨ ¬φ; pero Mc tiene que modelarla."]],"\n","así que busco φ",
   ["que valga en Mc = ⟨{◦, □, △}⟩ y falle en alguna otra estructura","Las dos mitades juntas.","qué busco",["que valga en Mc y en toda estructura","Eso es ⊨ φ, lo contrario."]]]},
 {id:"c2",k:"seq",t:"c) elegir φ con lo que ya tenés",p:"Paso 2: ¿qué fórmula ya leída distingue a Mc de M1 = ⟨{◦}⟩?",mo:1,sl:["φ :=",["β","Mc tiene dos elementos distintos y M1 no.","la fórmula",["α","En Mc no vale α: ◦, □ y △ son tres distintos."],["¬β","En Mc hay dos elementos distintos: Mc ⊭ ¬β."]],"\n","⊭ φ porque",
   ["M1 ⊭ β (parte b)","M1 es la estructura donde falla.","la primera razón",["ninguna estructura modela β","Mc la modela."]],"\n","Mc ⊨ φ porque",
   ["a = ◦ y b = □ cumplen (B)","Un par de elementos distintos de Mc.","la segunda razón",["a = ◦ y b = ◦ cumplen (B)","(B) pide a ≠ b."]]]}]);

/* --- Segundo parcial · Ejercicio 4: Mod, Th, Cons y consistencia --- */
lgEx("2P26 · Ej. 4 (consistencia)","lg4",LGI.con.concat(EJT),["Segundo parcial de Lógica, 10 de julio de 2026 · Ejercicio 4 (15 puntos)","Sea L un lenguaje de primer orden con igualdad, con tipo de similaridad ⟨−; 1; 0⟩, con símbolo de función f. Considere el conjunto: Γ = {(∀x)(∀y)(¬x =′ y → ¬f(x) =′ f(y))} ⊆ SENT y sea M1 la siguiente estructura: M1 = ⟨{0, 1}, id⟩",
 "a. Demuestre que M1 ∈ Mod(Γ).","b. Demuestre que Cons(Γ) ⊆ Th({M1}).","c. Considere la sentencia φ = (∀x)f(x) =′ x. Demuestre que φ ∉ Cons(Γ).","d. Determine si se cumple que Cons(Γ) = Th({M1}). Justifique.","e. ¿Cons(Γ) es consistente maximal? Justifique.",
 "Nota: Puede utilizar sin probar que para cualquier estructura M = ⟨U, F⟩, se cumple que: M ⊨ Γ ⇔ (∀a ∈ U)(∀b ∈ U)(a ≠ b ⇒ F(a) ≠ F(b)) y que M ⊨ φ ⇔ (∀a ∈ U) F(a) = a"],[
 {id:"a",k:"cad",t:"a) M1 ∈ Mod(Γ)",p:"Armá la cadena.",ini:"M1 ∈ Mod(Γ)",st:["⇔ (def. Mod)   M1 ⊨ Γ","⇔ (nota aplicada a M1)   (∀n, m ∈ {0, 1})(n ≠ m ⇒ id(n) ≠ id(m))","⇔ (def. id)   (∀n, m ∈ {0, 1})(n ≠ m ⇒ n ≠ m), que se cumple"],
  no:[["⇔ (def. Mod)   Γ ⊨ M1","Mod(Γ) son las estructuras M con M ⊨ Γ."],["⇔ (nota aplicada a M1)   (∀n ∈ {0, 1}) id(n) = n","Esa es la nota para φ, no para Γ."]]},
 {id:"b",k:"cad",t:"b) Cons(Γ) ⊆ Th({M1})",p:"Sea φ ∈ Cons(Γ) arbitraria. Llegá a φ ∈ Th({M1}).",mo:1,ini:"φ ∈ Cons(Γ)",st:["⇔ (def. Cons)   Γ ⊢ φ","⇔ (corrección y completitud)   Γ ⊨ φ","⇔ (def. ⊨)   (∀M)(M ⊨ Γ ⇒ M ⊨ φ)","⇒ (parte a: M1 ⊨ Γ)   M1 ⊨ φ","⇔ (def. Th)   φ ∈ Th({M1})"],
  no:[["⇔ (parte a: M1 ⊨ Γ)   M1 ⊨ φ","Solo vale ⇒: de M1 ⊨ φ no se vuelve a Γ ⊨ φ (habría que mirar todos los modelos de Γ)."],["⇔ (def. ⊨)   (∃M)(M ⊨ Γ y M ⊨ φ)","Γ ⊨ φ habla de TODOS los modelos de Γ."],["⇔ (completitud)   Γ ⊨ φ","Para ⊢ ⇔ ⊨ hacen falta las dos: corrección (⊢ ⇒ ⊨) y completitud (⊨ ⇒ ⊢)."]]},
 {id:"c",k:"seq",t:"c) φ ∉ Cons(Γ)",p:"¿Cómo se prueba y con qué estructura?",mo:1,sl:["hay que dar",["una estructura M con M ⊨ Γ y M ⊭ φ","φ ∉ Cons(Γ) es Γ ⊬ φ, que equivale a Γ ⊭ φ (corrección y completitud).","qué hay que mostrar",["una derivación de ¬φ desde Γ","No se pide eso: φ ∉ Cons(Γ) es Γ ⊬ φ, y se prueba con un contramodelo."]]]},
 {id:"c2",k:"est",t:"c) armar M2",p:"Armá M2 = ⟨U, F⟩ (tipo ⟨−; 1; 0⟩).",mo:1,ms:[{nm:"M2",tp:[["U","U"],["F","F","F"]]}],sl:["M2 tiene que cumplir (nota):",["F inyectiva y algún F(a) ≠ a","M ⊨ Γ pide inyectiva; M ⊭ φ pide que NO todo a cumpla F(a) = a.","qué pide",["F inyectiva y F(a) ≠ a para todo a","Para M ⊭ φ alcanza con UN a que se mueva (negar un ∀ da un ∃)."],["F no inyectiva y algún F(a) ≠ a","Tiene que modelar Γ: F inyectiva."]],
   ["{0, 1}","Con uno solo, la única F es la identidad: vale φ.","U",["{0}","F(0) = 0 obligatoriamente: M ⊨ φ."]],
   ["F(0) = 1, F(1) = 0 (intercambio)","El ejemplo típico de inyectiva que no es la identidad.","F",["F = id","id(n) = n: M ⊨ φ (es M1)."],["F(0) = 1, F(1) = 1","F(0) = F(1) con 0 ≠ 1: no es inyectiva, no modela Γ."]]]},
 {id:"d",k:"seq",t:"d) ¿Cons(Γ) = Th({M1})?",p:"Paso 1: ¿qué hay que ver para una igualdad de conjuntos, y qué ya tenés?",mo:1,sl:["Cons(Γ) = Th({M1}) ⇔",["Cons(Γ) ⊆ Th({M1}) y Th({M1}) ⊆ Cons(Γ)","Doble inclusión.","la igualdad",["Cons(Γ) ⊆ Th({M1})","Una sola inclusión no alcanza."]],"\n","la parte b ya da",
   ["Cons(Γ) ⊆ Th({M1}); falta ver Th({M1}) ⊆ Cons(Γ)","Queda la otra inclusión.","lo que falta",["las dos inclusiones","La parte b da solo una."]]]},
 {id:"d2",k:"seq",t:"d) la otra inclusión",p:"Paso 2: ¿hay una sentencia de Th({M1}) que no esté en Cons(Γ)? Buscala en las partes anteriores.",mo:1,sl:["sí:",["φ = (∀x)f(x) =′ x: M1 ⊨ φ (id(n) = n) y φ ∉ Cons(Γ) (parte c)","Está en uno y no en el otro.","el testigo",["una sentencia de Cons(Γ) que no está en Th({M1})","Esa inclusión ya vale (parte b): no hay."]],"\n","d:",
   ["NO se cumple","Falla Th({M1}) ⊆ Cons(Γ).","el veredicto",["SÍ se cumple","φ está en Th({M1}) y no en Cons(Γ)."]]]},
 {id:"e",k:"seq",t:"e) ¿Cons(Γ) es consistente maximal?",p:"Paso 1: ¿qué alcanza para ver que NO es maximal?",mo:1,sl:["para que NO sea maximal alcanza con",["un conjunto consistente que lo contenga estrictamente","Las fórmulas de más se le podrían agregar sin volverlo inconsistente.","qué alcanza",["ver que es consistente","Esa es la mitad que sí se cumple."]]]},
 {id:"e2",k:"seq",t:"e) usar lo que ya tenés",p:"Paso 2: ¿qué conjunto de las partes anteriores sirve?",mo:1,sl:["sirve",["Th({M1}): es consistente (M1 lo modela) y Cons(Γ) ⊊ Th({M1}) (partes b y d)","⊆ por b y ≠ por d.","el conjunto",["Th({M1}), porque Cons(Γ) ⊆ Th({M1})","Con ⊆ no alcanza: podrían ser iguales. Hace falta la parte d."]],"\n","e:",
   ["NO es consistente maximal","Está incluido estrictamente en un consistente.","el veredicto",["SÍ es consistente maximal","Cons(Γ) ⊊ Th({M1}), que es consistente."]]]}]);

/* ===== Práctica de tableau (21/11, pedido de Luca: «necesito un par de ejercicios más de tableau»). NO son de examen: los únicos tableaux de los
   exámenes traídos son del 1P26. Uno donde la consecuencia NO vale (rama abierta → contraejemplo) y otro con ¬. ===== */
/* 26/11 (exportación: 4 «No sé» en «las reglas que se usan», nota «tiene menos pasos de los que esperaba, pensé que antes había que separar
   ramas»): las dos prácticas pasan al motor tbEx (el tableau se arma dibujándose, con el tipo de regla dentro de cada «desarmo …»); se quitan la
   tarjeta de «elegí las reglas» (reconocer, no hacer) y el k:"tab" viejo. Van después de la escalera (Tableau 8). */
tbEx("Práctica · tableau 1 (contraejemplo)",["m:Tableau 8 · una fórmula en dos ramas:ej"],["Ejercicio de práctica (no es de un examen)","Determine mediante tableau semántico si: p → q ⊨ q → p"],["p → q"],"q → p","Una consecuencia que NO vale: queda una rama abierta y de ahí se lee el contraejemplo.");
tbEx("Práctica · tableau 2 (con ¬)",["m:Tableau 8 · una fórmula en dos ramas:ej"],["Ejercicio de práctica (no es de un examen)","Considere dos fórmulas α y β de PROP.","Determine mediante tableau semántico si: ¬(α ∨ β) ⊨ ¬α ∧ ¬β"],["¬(α ∨ β)"],"¬α ∧ ¬β","Primero lo que sigue en la misma rama (T.¬, F.∨), aunque la conclusión abra dos ramas: así lo de arriba ya está desarmado cuando se separan.");

/* ===== EJEMPLOS TÍPICOS (21/11, pedido de Luca): paquetes de práctica (no son de examen) con los ejemplos y contraejemplos triviales de cada
   situación, armados con fichas (k:"est"). Son previas (EJT) de los ejercicios de «dé una estructura». Cada tarjeta: decir la fórmula en palabras
   y armar la estructura más chica que la cumple. ===== */
lgEx("Práctica · ejemplos típicos 1 (igualdad)","lg4",LGI.mod.filter(t=>!EJT.includes(t)),["Ejemplos típicos (práctica, no es de un examen)","Lenguaje con igualdad, tipo ⟨−; −; 0⟩: no hay predicados, ni funciones, ni constantes. Una estructura es solo su universo U (los elementos de los que se habla): M = ⟨U⟩. x =′ y vale cuando x e y son el MISMO elemento.","Cada tarjeta: primero decí qué dice la fórmula; después elegí U."],[
 {id:"i0",k:"seq",t:"leer =′ en un par",th:"Sin predicados ni funciones, lo único que una fórmula puede hacer es comparar elementos con =′: por eso estas fórmulas hablan de CUÁNTOS elementos hay. x =′ y se interpreta como la igualdad: M ⊨ ā =′ b̄ quiere decir que a y b son el MISMO elemento. En U = {◦, □}: ◦ =′ ◦ vale; ◦ =′ □ no. Un ∀ sobre dos variables recorre TODOS los pares (también los de un elemento consigo mismo); un ∃ pide un par que sirva.",p:"Paso 1: en U = {◦, □}, ¿qué quiere decir M ⊨ ā =′ b̄, y qué recorre un ∀ sobre x e y?",sl:["M ⊨ ā =′ b̄ ⇔",["a y b son el mismo elemento","=′ se interpreta como la igualdad.","qué quiere decir",["a y b están en U","Todos los elementos están en U: eso no distingue nada."]],"\n","en U = {◦, □}:",
   ["◦ =′ ◦ vale y ◦ =′ □ no","◦ es ◦; ◦ y □ son distintos.","los casos",["◦ =′ □ vale","◦ y □ son dos elementos distintos."]],"\n","(∀x)(∀y) recorre",
   ["todos los pares: (◦, ◦), (◦, □), (□, ◦), (□, □)","Cada x con cada y, incluido un elemento consigo mismo.","los pares",["solo los pares de elementos distintos","También (◦, ◦) y (□, □)."]]]},
 {id:"i1",k:"est",t:"todos iguales",mo:1,th:"Cómo armar un ejemplo: 1) leé qué exige la fórmula; 2) elegí el universo más chico que alcance; 3) elegí P y F lo más simples posible (P vacío, P = todo U, F identidad, F constante) y cambialos solo si la fórmula lo exige. Las piezas que la fórmula no nombra pueden ser cualquiera: se pone la más simple. (∀x)(∀y) x =′ y se lee: tomes los dos elementos que tomes, son el mismo. Con U = {◦}, el único par es ◦, ◦: se cumple. Con U = {◦, □}, el par ◦, □ son distintos: falla. Por eso el universo de un solo elemento es el ejemplo típico de «todos iguales» o «a lo sumo uno». El universo nunca puede ser vacío.",p:"Armá M con M ⊨ (∀x)(∀y) x =′ y.",ms:[{nm:"M",tp:[["U","U"]]}],sl:["M ⊨ (∀x)(∀y) x =′ y ⇔",["para todo a ∈ U y todo b ∈ U: a = b","Cada ∀ recorre U; juntos recorren todos los pares (a, b).","la fórmula abierta",["para algún a y algún b de U: a = b","Eso sería (∃x)(∃y); con ∀ es para TODOS."]],"\n","o sea",
   ["tomes el par que tomes, son el mismo elemento: U tiene un solo elemento","Si hubiera dos elementos distintos, ese par no cumpliría a = b.","qué dice la fórmula",["U puede tener varios elementos, si alguno se repite","Con dos distintos, el par (◦, □) falla."]],
   ["{◦}","El universo unitario: el modelo trivial de «todos iguales» y de «a lo sumo n».","U",["{◦, □}","Con x = ◦, y = □: ◦ ≠ □, falla."],["∅","El universo no puede ser vacío."]]]},
 {id:"i2",k:"est",t:"dos distintos",th:"Cómo armar un ejemplo: 1) leé qué exige la fórmula; 2) elegí el universo más chico que alcance; 3) elegí P y F lo más simples posible (P vacío, P = todo U, F identidad, F constante) y cambialos solo si la fórmula lo exige. Las piezas que la fórmula no nombra pueden ser cualquiera: se pone la más simple. (∃x)(∃y)¬x =′ y se lee: hay dos elementos distintos. Con U = {◦, □} el testigo es x = ◦, y = □. Con U = {◦} el único par es ◦, ◦, que son iguales: falla. Dos elementos es el ejemplo típico de «al menos dos distintos».",p:"Armá M con M ⊨ (∃x)(∃y)¬x =′ y.",mo:1,ms:[{nm:"M",tp:[["U","U"]]}],sl:["M ⊨ (∃x)(∃y)¬x =′ y ⇔",["existen a ∈ U y b ∈ U con a ≠ b","Cada ∃ pide un testigo; ¬ =′ es «distintos».","la fórmula abierta",["para todo a, b ∈ U: a ≠ b","Con ∃ alcanza un par, no todos."]],"\n","o sea",["hay al menos 2 elementos distintos","Un ∃: alcanza un par distinto.","qué dice la fórmula",["todos los elementos son distintos","Eso pediría un ∀."],["hay exactamente 2 elementos","No pone tope: con más también vale."]],
   ["{◦, □}","El ejemplo más chico de «al menos 2».","U",["{◦}","El único par posible es ◦, ◦ y ◦ = ◦: falla."]]]}]);
lgEx("Práctica · ejemplos típicos 2 (predicados y funciones)","lg4",LGI.mod.filter(t=>!EJT.includes(t)),["Ejemplos típicos (práctica, no es de un examen)","Lenguaje con igualdad, tipo ⟨1; 1; 0⟩: un predicado P de un lugar, una función f de un lugar, ninguna constante. Una estructura es M = ⟨U, P, F⟩: U = los elementos (p. ej. {◦, □}); P = cuáles de esos elementos cumplen P (una parte de U); F = una tabla que a cada elemento le asigna otro elemento (lo que hace f).","Primero: cómo se lee P(x) y el ∀ en una estructura. Después, en cada tarjeta: decí qué dice la fórmula y elegí U, P y F, en ese orden."],[
 {id:"j0",k:"seq",t:"leer P en un elemento",th:"ā (a con techito) es el NOMBRE del elemento a: el lenguaje no tiene constantes, así que para hablar de un elemento concreto de U se agrega un símbolo ā que la estructura interpreta como a. P(◦) se lee «◦ cumple P» (con ◦ y □ el techito no se ve bien en la pantalla, así que se escribe P(◦) para el nombre de ◦; 23/11). En una estructura, el predicado P se interpreta como un SUBCONJUNTO de U: los elementos que cumplen P. Por eso M ⊨ P(ā) (a cumple P) quiere decir a ∈ P. Ejemplo: en M = ⟨{◦, □}, {◦}, id⟩, P = {◦}: ◦ cumple P y □ no.",p:"Paso 1: en M = ⟨{◦, □}, {◦}, id⟩, o sea P = {◦}, ¿qué es ā y qué quiere decir M ⊨ P(ā)?",sl:["ā es",["el nombre (en el lenguaje) del elemento a de U","El lenguaje no tiene constantes: para hablar de un elemento concreto se usa su nombre ā, que la estructura interpreta como a (nota de Luca 23/11: «no sé qué es la a con techito»).","qué es ā",["una variable","Una variable (x) no nombra a ningún elemento fijo; ā siempre es a."],["una constante del lenguaje","El tipo ⟨1; 1; 0⟩ no tiene constantes: ā se agrega para nombrar al elemento a."]],"\n","M ⊨ P(ā) ⇔",["a ∈ P (a está en el conjunto que interpreta a P)","P es un subconjunto de U: «a cumple P» es «a está en ese subconjunto».","qué quiere decir",["a ∈ U","Todo elemento está en U; P es solo una parte de U."],["P = a","P es un conjunto de elementos, no un elemento."]],"\n","en este M:",
   ["M ⊨ P(◦) y M ⊭ P(□)","◦ ∈ {◦} y □ ∉ {◦}.","los dos casos",["M ⊨ P(◦) y M ⊨ P(□)","□ ∉ P = {◦}."],["M ⊭ P(◦) y M ⊭ P(□)","◦ ∈ P = {◦}: ◦ sí cumple P."]]]},
 {id:"j0b",k:"seq",t:"leer el ∀",th:"M ⊨ (∀x)φ quiere decir: para TODO elemento a de U, φ vale con x = a (2.4.5). Con φ = P(x): para todo a ∈ U, a ∈ P. En palabras: todo elemento está en P. Se chequea elemento por elemento: si uno solo queda afuera, falla. El ∃ es al revés: alcanza con uno.",p:"Paso 2: ¿qué quiere decir M ⊨ (∀x)P(x)?",mo:1,sl:["M ⊨ (∀x)P(x) ⇔",["para todo a ∈ U: M ⊨ P(ā)","El ∀ recorre los elementos del universo, uno por uno (2.4.5).","el ∀",["para algún a ∈ U: M ⊨ P(ā)","Eso es el ∃."]],"\n","con el paso 1, o sea",
   ["todo a ∈ U está en P","M ⊨ P(ā) es a ∈ P, y eso para todos.","en palabras",["algún a ∈ U está en P","Eso es (∃x)P(x)."]],"\n","en M = ⟨{◦, □}, {◦}, id⟩:",
   ["no vale, porque □ ∉ P","Falla con a = □.","¿vale?",["vale, porque ◦ ∈ P","Alcanzaría para un ∃; el ∀ pide todos los elementos."]]]},
 {id:"j1",k:"est",t:"∀ con un predicado",mo:1,th:"Cómo armar un ejemplo: 1) leé qué exige la fórmula; 2) elegí el universo más chico que alcance; 3) elegí P y F lo más simples posible (P vacío, P = todo U, F identidad, F constante) y cambialos solo si la fórmula lo exige. Las piezas que la fórmula no nombra pueden ser cualquiera: se pone la más simple. (∀x)P(x) se lee: todo elemento de U está en P. Ejemplo con U = {◦, □}: si P = {◦, □} vale; si P = {◦}, □ queda afuera y falla. La forma trivial de que un ∀ sobre P valga es P = todo U. f no aparece en la fórmula: F puede ser cualquiera, y se pone la identidad (F(x) = x).",p:"Armá M con M ⊨ (∀x)P(x).",ms:[{nm:"M",tp:[["U","U"],["R","P","P"],["F","F","F"]]}],sl:["(∀x)P(x) dice que",["todo elemento está en P","Un ∀: ninguno puede quedar afuera.","qué dice la fórmula",["algún elemento está en P","Eso sería (∃x)P(x)."]],
   ["{◦, □}","Cualquier universo sirve; lo que importa es P.","U",["∅","El universo no puede ser vacío."]],
   ["{◦, □}","P = U: la forma trivial de que un ∀ valga.","P",["{◦}","□ ∉ P: falla con x = □."],["∅","Nadie está en P: falla."]],
   ["cualquiera (f no aparece), p. ej. F(x) = x","f no aparece en la fórmula: cualquier F sirve. Se anota la más simple (la identidad), pero no es obligatoria.","F"]]},
 {id:"j2",k:"est",t:"∃ algo afuera",th:"Cómo armar un ejemplo: 1) leé qué exige la fórmula; 2) elegí el universo más chico que alcance; 3) elegí P y F lo más simples posible (P vacío, P = todo U, F identidad, F constante) y cambialos solo si la fórmula lo exige. Las piezas que la fórmula no nombra pueden ser cualquiera: se pone la más simple. (∃x)¬P(x) se lee: hay un elemento que no está en P. La forma trivial es P = ∅ (nadie está en P). Con P = U nadie queda afuera y falla.",p:"Armá M con M ⊨ (∃x)¬P(x).",mo:1,ms:[{nm:"M",tp:[["U","U"],["R","P","P"],["F","F","F"]]}],sl:["(∃x)¬P(x) dice que",["algún elemento queda afuera de P","Un ∃: alcanza uno (testigo).","qué dice la fórmula",["ningún elemento está en P","Eso sería (∀x)¬P(x). Igual, P = ∅ lo cumple."]],
   ["{◦, □}","Cualquier universo sirve.","U",["∅","El universo no puede ser vacío."]],
   ["∅","P vacío: la forma trivial de que algo quede afuera (también sirve {◦}, con □ de testigo).","P",["{◦, □}","P = U: nadie queda afuera, falla."]],
   ["cualquiera (f no aparece), p. ej. F(x) = x","f no aparece en la fórmula: cualquier F sirve. Se anota la más simple (la identidad), pero no es obligatoria.","F"]]},
 {id:"j2b",k:"seq",t:"leer f en un elemento",th:"f es un SÍMBOLO del lenguaje (como una tecla de función que todavía no hace nada). La estructura le da significado con una TABLA F: para cada elemento dice a qué elemento va. Calcular f(◦) en M es mirar la fila de ◦ en la tabla. Con la tabla F(◦) = □, F(□) = □: f(◦) vale □ y f(□) vale □. En general, f(ā) vale F(a): lo que la tabla le asigna a a. Por eso f(ā) =′ ā dice «la tabla deja a a en su lugar» (F(a) = a): en esta tabla, □ queda fijo y ◦ no (◦ va a □).",p:"Paso previo. M tiene U = {◦, □} y la tabla de f es: F(◦) = □, F(□) = □. Calculá con la tabla.",mo:1,sl:["f(◦) vale",["□ (la fila de ◦ en la tabla dice □)","Se mira la tabla: F(◦) = □. f(◦) es lo que SALE de la tabla, no lo que entra: como en matemática, si f(x) = x², f(3) vale 9, no 3.","f(◦)",["◦","Eso sería si F dejara a ◦ en su lugar; la tabla dice F(◦) = □."]],"\n","f(□) vale",
   ["□ (la fila de □ dice □)","F(□) = □.","f(□)",["◦","La tabla dice F(□) = □."]],"\n","en general, f(ā) vale",
   ["F(a): lo que la tabla le asigna a a","Es lo que hiciste en los dos casos.","en general",["a","Solo si la tabla fuera la identidad; acá f(◦) = □ ≠ ◦."]],"\n","entonces M ⊨ f(ā) =′ ā dice",
   ["F(a) = a: la tabla deja a a en su lugar (queda fijo)","=′ es «son el mismo elemento».","qué dice",["F(a) ∈ U","Toda imagen está en U: no dice nada."]],"\n","en esta tabla queda fijo",
   ["□ (F(□) = □), y ◦ no (F(◦) = □ ≠ ◦)","Se mira fila por fila.","quién queda fijo",["◦","F(◦) = □: ◦ se mueve."]]]},
 {id:"j3",k:"est",t:"f sin puntos fijos",th:"Cómo armar un ejemplo: 1) leé qué exige la fórmula; 2) elegí el universo más chico que alcance; 3) elegí P y F lo más simples posible (P vacío, P = todo U, F identidad, F constante) y cambialos solo si la fórmula lo exige. Las piezas que la fórmula no nombra pueden ser cualquiera: se pone la más simple. (∀x)¬f(x) =′ x se lee: F no deja a ningún elemento en su lugar. Con un solo elemento es imposible (F(◦) = ◦ a la fuerza). Con U = {◦, □}, el intercambio F(◦) = □, F(□) = ◦ mueve a los dos: es el ejemplo típico.",p:"Armá M con M ⊨ (∀x)¬f(x) =′ x.",mo:1,ms:[{nm:"M",tp:[["U","U"],["R","P","P"],["F","F","F"]]}],sl:["(∀x)¬f(x) =′ x dice que",["F(a) ≠ a para todo a: f mueve a todos","Un ∀: ninguno queda fijo.","qué dice la fórmula",["algún F(a) ≠ a","Un ∀: TODOS se mueven."]],
   ["{◦, □}","Hacen falta dos: con uno solo, F(◦) = ◦.","U",["{◦}","La única F posible es F(◦) = ◦: punto fijo."]],
   ["cualquiera (P no aparece), p. ej. ∅","P no aparece en las fórmulas: cualquier P sirve; ∅ es la más simple.","P"],
   ["F(◦) = □, F(□) = ◦ (intercambio)","El ejemplo típico sin puntos fijos.","F",["F = id","Todos quedan fijos."],["F(x) = ◦ (constante)","F(◦) = ◦: ◦ queda fijo."]]]},
 {id:"j3b",k:"seq",t:"leer P(f(x))",th:"M ⊨ P(f(ā)) quiere decir F(a) ∈ P: primero se calcula la imagen F(a) con la tabla, después se mira si está en P. (∀x)P(f(x)) pide eso para todo a: todas las IMÁGENES caen en P. No pide que todo U esté en P: un elemento que no es imagen de nadie puede quedar afuera.",p:"Paso previo: en U = {◦, □}, P = {◦}, F(x) = ◦ (constante), ¿qué dice M ⊨ P(f(ā)) y vale (∀x)P(f(x))?",mo:1,sl:["M ⊨ P(f(ā)) ⇔",["F(a) ∈ P","Primero la imagen con la tabla, después si está en P.","qué quiere decir",["a ∈ P","P se aplica a f(a), no a a."]],"\n","en este M, (∀x)P(f(x))",
   ["vale: F(◦) = ◦ ∈ P y F(□) = ◦ ∈ P","Todas las imágenes son ◦, que está en P.","¿vale?",["no vale: □ ∉ P","□ no es imagen de nadie: (∀x)P(f(x)) mira las imágenes, no a □."]]]},
 {id:"j4",k:"est",t:"imagen de f dentro de P",th:"Cómo armar un ejemplo: 1) leé qué exige la fórmula; 2) elegí el universo más chico que alcance; 3) elegí P y F lo más simples posible (P vacío, P = todo U, F identidad, F constante) y cambialos solo si la fórmula lo exige. Las piezas que la fórmula no nombra pueden ser cualquiera: se pone la más simple. (∀x)P(f(x)) se lee: para todo elemento a, F(a) está en P (habla de las IMÁGENES de f, no de todo U). La forma trivial es F constante: mandar todo a un elemento de P. Así puede quedar otro elemento afuera de P, que es lo que pide (∃x)¬P(x).",p:"Armá M con M ⊨ (∀x)P(f(x)) y M ⊨ (∃x)¬P(x).",mo:1,ms:[{nm:"M",tp:[["U","U"],["R","P","P"],["F","F","F"]]}],sl:["las fórmulas dicen que",["toda imagen de f cae en P y algún elemento queda afuera de P","El ∀ habla de las imágenes de f, no de todo el universo.","qué dice la fórmula",["todo elemento está en P y algún elemento queda afuera de P","(∀x)P(f(x)) no pide que todo el universo esté en P: solo las imágenes de f. Leído así sería imposible."]],
   ["{◦, □}","Uno en P (◦) y uno afuera (□).","U",["{◦}","◦ tendría que estar en P (imagen de f) y afuera a la vez."]],
   ["{◦}","◦ en P, □ afuera (testigo del ∃).","P",["{◦, □}","Nadie queda afuera de P."]],
   ["F(x) = ◦ (constante)","La forma trivial de que toda imagen caiga en P: mandar todo a un elemento de P.","F",["F = id","F(□) = □ ∉ P: falla el ∀."],["F(◦) = □, F(□) = ◦","F(◦) = □ ∉ P: falla el ∀."]]]},
 {id:"j5",k:"est",t:"inyectiva que no es la identidad",th:"Cómo armar un ejemplo: 1) leé qué exige la fórmula; 2) elegí el universo más chico que alcance; 3) elegí P y F lo más simples posible (P vacío, P = todo U, F identidad, F constante) y cambialos solo si la fórmula lo exige. Las piezas que la fórmula no nombra pueden ser cualquiera: se pone la más simple. La primera fórmula dice que elementos distintos van a imágenes distintas (F inyectiva). M ⊭ (∀x)f(x) =′ x dice que NO todos quedan fijos: alcanza con que uno se mueva. El intercambio en {◦, □} es inyectivo y mueve a los dos.",p:"Armá M con M ⊨ (∀x)(∀y)(¬x =′ y → ¬f(x) =′ f(y)) y M ⊭ (∀x)f(x) =′ x.",mo:1,ms:[{nm:"M",tp:[["U","U"],["R","P","P"],["F","F","F"]]}],sl:["las fórmulas dicen que",["F es inyectiva y mueve al menos a un elemento","La primera: distintos van a distintos. La segunda, negada: algún F(a) ≠ a.","qué dice la fórmula",["F es inyectiva y mueve a todos","⊭ (∀x)… es «no todos quedan fijos»: alcanza uno que se mueva."]],
   ["{◦, □}","Con uno solo, la única F es la identidad.","U",["{◦}","F(◦) = ◦ obligatoriamente: vale (∀x)f(x) =′ x."]],
   ["cualquiera (P no aparece), p. ej. ∅","P no aparece en las fórmulas: cualquier P sirve; ∅ es la más simple.","P"],
   ["F(◦) = □, F(□) = ◦ (intercambio)","Inyectiva y mueve a los dos.","F",["F = id","Es inyectiva, pero no mueve a nadie."],["F(x) = ◦ (constante)","F(◦) = F(□) con ◦ ≠ □: no es inyectiva."]]]}]);

/* ===== CONCEPTO + PREGUNTA (22/11, pedido de Luca: «no me está siendo óptimo aprender teórico con fichas»; «lo mejor sea explicar un concepto y
   hacer una pregunta para verificar si se entendió»; «las tarjetas tienen que servir para incorporar los conceptos y la sucesión de pensamientos
   que debo tener para realizar los ejercicios»). Reemplaza las cadenas de pruebas del teórico (07_PropComp, 12_PredComp).
   Tarjeta con c.ex: arriba va la explicación del concepto (corta, con un ejemplo) y abajo una o dos preguntas que solo se contestan si se entendió.
   La explicación es también su «No sé». Orden: los conceptos en el orden en que se usan al resolver; después los ejercicios del práctico 5, cada uno
   desarmado en la sucesión de pensamientos (qué me piden → qué camino → qué busco → lo encuentro → concluyo). ===== */
lgEx("Teórico · consistencia (PROP)","lg4",[],["Conceptos del teórico (07_PropComp) y del práctico 5"],[
 {id:"k1",k:"seq",t:"⊢ y ⊨",ex:"⊢ (UNA raya) es sintaxis: Γ ⊢ α se lee «de Γ se DERIVA α»: hay una derivación (un árbol de deducción natural) con hipótesis en Γ y conclusión α. ⊨ (DOS rayas) es semántica: Γ ⊨ α se lee «α es consecuencia de Γ»: toda valuación que hace 1 a TODO Γ hace 1 a α. Tachados (⊬, ⊭) son la negación: no se deriva, no es consecuencia. Sin nada a la izquierda: ⊢ α es «α es un teorema» y ⊨ α es «α es tautología». Ejemplo: {p0, p0 → p1} ⊨ p1, porque si v(p0) = 1 y v(p0 → p1) = 1, entonces v(p1) = 1; y {p0, p0 → p1} ⊢ p1 por E→.",p:"Primero leé los signos; después usalos.",sl:["Γ ⊢ α (una raya) dice",["hay una derivación de α con hipótesis en Γ","Sintaxis: reglas y árboles.","una raya",["toda valuación que hace 1 a Γ hace 1 a α","Esa es ⊨, la de dos rayas."]],"\n","Γ ⊨ α (dos rayas) dice",
   ["toda valuación que hace 1 a todo Γ hace 1 a α","Semántica: valuaciones.","dos rayas",["hay una derivación de α desde Γ","Esa es ⊢, la de una raya."]],"\n","para mostrar Γ ⊨ α con valuaciones, mirás",
   ["todas las que hacen 1 a todo Γ, y ves que hacen 1 a α","Las demás no importan: ⊨ solo habla de las que satisfacen Γ.","cuáles",["una que haga 1 a Γ y a α","Un ejemplo no alcanza: tienen que ser TODAS."],["todas las valuaciones","Las que no satisfacen Γ no cuentan."]]]},
 {id:"k2",k:"seq",t:"corrección y completitud",ex:"Corrección: si Γ ⊢ α, entonces Γ ⊨ α. Completitud: si Γ ⊨ α, entonces Γ ⊢ α. Juntas: ⊢ y ⊨ son lo mismo, y en un ejercicio podés pasar de uno al otro citando el teorema. El uso más común: para mostrar que algo NO se deriva (Γ ⊬ α), das una valuación que haga 1 a Γ y 0 a α; por corrección, α no se deriva.",p:"Verificá que se entendió.",mo:1,sl:["probaste Γ ⊨ α y te piden Γ ⊢ α: citás",["completitud","Va de ⊨ a ⊢.","el teorema",["corrección","Corrección va de ⊢ a ⊨."]],"\n","para mostrar Γ ⊬ α conviene",
   ["una valuación que haga 1 a Γ y 0 a α (corrección)","Si se derivara, por corrección esa valuación no podría existir.","el camino",["intentar derivar α y no poder","No poder no prueba nada: puede faltar ingenio."]]]},
 {id:"k3",k:"seq",t:"consistente",ex:"Γ es consistente si Γ ⊬ ⊥: de Γ no se deriva una contradicción. Equivale a que ALGUNA valuación haga 1 a TODAS sus fórmulas a la vez. Inconsistente (Γ ⊢ ⊥) equivale a: Γ deriva cualquier fórmula, y ninguna valuación lo satisface. Ejemplo: {p0, ¬p1} es consistente (v(p0) = 1, v(p1) = 0); {p0, ¬p0} no.",p:"Verificá que se entendió.",mo:1,sl:["{p0, p0 → p1, ¬p1} es",["inconsistente: si v(p0) = 1 y v(p0 → p1) = 1, entonces v(p1) = 1, y ¬p1 falla","Las tres juntas no pueden valer 1.","el veredicto",["consistente: cada fórmula sola se puede hacer 1","Tienen que valer 1 TODAS A LA VEZ, con la misma valuación."]],"\n","un conjunto inconsistente deriva",
   ["cualquier fórmula (de ⊥ sale todo con E⊥)","Lema 1.6.3.","qué deriva",["solo ⊥","Con E⊥, de ⊥ sale cualquier fórmula."]]]},
 {id:"k4",k:"seq",t:"el pensamiento: ¿es consistente?",ex:"Cómo se decide: 1) empezá por las fórmulas que OBLIGAN un valor (una letra sola, una negación de una letra, un ∧): fijan letras. 2) Con eso, mirá las demás (→, ∨, ↔), que suelen dejar opciones. 3) Si llegás a una valuación que hace 1 a todas, es consistente (condición suficiente). Si todo intento choca (una letra tendría que valer 0 y 1), es inconsistente: lo mostrás derivando ⊥. Si nada obliga, probá todo en 0 o todo en 1. El tableau con T. en todas las fórmulas hace esto mismo ordenado: una rama abierta da la valuación.",p:"Aplicalo a {p2, ¬p2 ∨ p3, ¬p3}.",mo:1,sl:["empiezo por",["p2 y ¬p3: obligan v(p2) = 1 y v(p3) = 0","Son las que fijan valores.","por dónde",["¬p2 ∨ p3","Un ∨ deja opciones: conviene dejarlo para después."]],"\n","entonces ¬p2 ∨ p3 vale",
   ["0 ∨ 0 = 0: el conjunto es inconsistente","No hay otra opción: p2 y p3 ya estaban fijas.","el resultado",["1: el conjunto es consistente","¬p2 vale 0 y p3 vale 0."]]]},
 {id:"k5",k:"seq",t:"agregar una fórmula",ex:"Lema 1.6.5: si Γ ∪ {¬φ} es inconsistente, entonces Γ ⊢ φ (RAA: suponiendo ¬φ llegaste a ⊥). Si Γ ∪ {φ} es inconsistente, entonces Γ ⊢ ¬φ (I¬). Leído al revés: si Γ ⊬ φ, a Γ se le puede agregar ¬φ sin perder la consistencia.",p:"Verificá que se entendió.",mo:1,sl:["Γ ∪ {p3} es inconsistente, entonces",["Γ ⊢ ¬p3","Lo agregado fue p3: I¬ da ¬p3.","qué se deriva",["Γ ⊢ p3","Al revés: agregar p3 rompe todo porque Γ ya deriva ¬p3."]]]},
 {id:"k6",k:"seq",t:"independiente",ex:"φ es independiente de Γ si Γ ⊬ φ y Γ ⊬ ¬φ: Γ no decide φ, ni para un lado ni para el otro. Cada mitad se muestra con corrección leída al revés: para ver que Γ ⊬ φ alcanza con UNA valuación que haga 1 a todo Γ y 0 a φ (si φ se derivara, por corrección valdría 1 en esa valuación). Para ver que Γ ⊬ ¬φ, otra valuación que haga 1 a Γ y 0 a ¬φ, o sea 1 a φ. En total, dos valuaciones que satisfacen Γ y no coinciden en φ.",p:"Paso a paso: ¿p1 es independiente de {p0}?",mo:1,sl:["para ver que {p0} ⊬ p1 busco una valuación con",["p0 = 1 y p1 = 0","Satisface {p0} y hace 0 a p1: por corrección, p1 no se deriva.","la primera",["p0 = 1 y p1 = 1","Hace 1 a p1: no muestra que p1 no se derive."],["p0 = 0 y p1 = 0","No satisface {p0}: no cuenta."]],"\n","para ver que {p0} ⊬ ¬p1 busco una valuación con",
   ["p0 = 1 y p1 = 1","Satisface {p0} y hace 0 a ¬p1.","la segunda",["p0 = 1 y p1 = 0","Hace 1 a ¬p1: no muestra nada sobre ¬p1."]],"\n","conclusión:",
   ["p1 es independiente de {p0}","Ni p1 ni ¬p1 se derivan.","el veredicto",["p1 es independiente porque p1 no está en {p0}","No pertenecer no alcanza: {p0} no contiene a p0 ∧ p0 y sin embargo lo deriva."]]]},
 {id:"k7",k:"seq",t:"consistente maximal",ex:"Cómo se lee {φ | v(φ) = 1}: «el conjunto de TODAS las fórmulas φ que valen 1 en v», o sea todo lo verdadero en v. Ejemplo: si v(p0) = 1 y las demás letras valen 0, adentro están p0, ¬p1, p0 ∨ p7, ¬⊥, p1 → p2, … (infinitas fórmulas); afuera quedan p1, p0 ∧ p1, ⊥, … Γ es consistente maximal si es consistente y no se le puede agregar ninguna fórmula de afuera sin volverlo inconsistente. Equivale (ejercicio 5): para toda φ, φ ∈ Γ o ¬φ ∈ Γ. El ejemplo típico es {φ | v(φ) = 1}: si una φ queda afuera es porque v(φ) = 0, entonces ¬φ está adentro, y agregar φ junta φ con ¬φ. Habla de PERTENECER.",p:"Primero leé el conjunto; después la propiedad.",mo:1,sl:["con v(p0) = 1 y el resto en 0, {φ | v(φ) = 1} contiene",["p0, ¬p1, p0 ∨ p7, ¬⊥, …: todas las fórmulas verdaderas en v","No solo letras: cualquier fórmula que v haga 1.","qué contiene",["solo p0: las letras que valen 1","También están todas las fórmulas compuestas que valen 1, como ¬p1 o p0 ∨ p7."],["p0 y p1","v(p1) = 0: p1 queda afuera (y ¬p1 adentro)."]],"\n","{p0, p1} es consistente maximal?",
   ["no: ni p2 ni ¬p2 están, y se le puede agregar p2","Le faltan fórmulas.","el veredicto",["sí: es consistente","Consistente no alcanza: además no se le tiene que poder agregar nada."]],"\n","{φ | v(φ) = 1} es maximal porque",
   ["si φ no está, v(φ) = 0, así que ¬φ está, y agregar φ da φ y ¬φ juntas","Para toda φ, está ella o su negación.","por qué",["tiene infinitas fórmulas","La cantidad no importa."]]]},
 {id:"k8",k:"seq",t:"teoría",ex:"T es una teoría si Cons(T) ⊆ T: todo lo que T deriva ya está en T. Una teoría casi siempre es INFINITA y no se arma agregando fórmulas de a una (no terminarías nunca): se define de una vez, por ejemplo Cons({p0}) = el conjunto de todas las fórmulas que se derivan de p0 (p0, p0 ∧ p0, p0 ∨ p7, ¬¬p0, …). Para ver que un conjunto NO es teoría alcanza con UNA fórmula que deriva y no tiene. Ejemplos: Cons(Γ) para cualquier Γ, todo consistente maximal (Lema 1.6.8), PROP. Una teoría inconsistente es PROP: deriva todo, y todo lo que deriva está adentro.",p:"Verificá que se entendió.",mo:1,sl:["{p0} es una teoría?",["no: deriva p0 ∧ p0 y no lo tiene","Le faltan sus consecuencias.","el veredicto",["sí: tiene a su única hipótesis","Teoría pide tener TODO lo que se deriva."]],"\n","Cons(Γ) es siempre",
   ["una teoría","Lo que se deriva de lo derivable ya se deriva de Γ.","qué es Cons(Γ)",["consistente","Si Γ es inconsistente, Cons(Γ) = PROP."]]]},
 {id:"k9",k:"seq",t:"completo",ex:"Γ es completo si es consistente y decide todo: para toda φ, Γ ⊢ φ o Γ ⊢ ¬φ. Habla de DERIVAR. Equivale (ejercicio 17) a que exista una ÚNICA valuación que satisface Γ: Γ fija el valor de cada letra. Y Cons(Γ) es consistente maximal si y solo si Γ es completo (ejercicio 7).",p:"Verificá que se entendió.",mo:1,sl:["{p0, p1} es completo?",["no: p2 queda libre, hay dos valuaciones que lo satisfacen","Γ ⊬ p2 y Γ ⊬ ¬p2.","el veredicto",["sí: es consistente","Además tiene que decidir toda φ."]],"\n","P = {p0, p1, p2, …} es completo porque",
   ["la única valuación que lo satisface es la que hace 1 a todas las letras","Cada pi ∈ P obliga v(pi) = 1.","por qué",["contiene a todas las letras","Lo que importa es que fija una sola valuación."]]]},
 {id:"k10",k:"seq",t:"completo no es maximal",ex:"La intuición: completo = «DECIDE todo derivando» (cada φ o su negación SE DERIVA); maximal = «ya TIENE todo escrito adentro» (cada φ o su negación PERTENECE). P = {p0, p1, …} es como una lista de axiomas: fija la valuación, así que deriva todo lo verdadero, pero no lo tiene escrito (p0 ∧ p1 se deriva y no está en P). Cons(P), la lista completa de lo que deriva, sí es maximal. Completo (⊢) y maximal (∈) no son lo mismo. P = {p0, p1, …} es completo, pero no es maximal: p0 ∧ p1 no está en P y se puede agregar sin problema. Lo que sí vale: Cons(P) es maximal (ejercicio 7). Y un maximal es exactamente una teoría con una única valuación (ejercicio 9).",p:"Verificá que se entendió.",mo:1,sl:["P = {p0, p1, …} es consistente maximal?",["no: p0 ∧ p1 ∉ P y agregarla no rompe nada","Completo no implica maximal.","el veredicto",["sí, porque es completo","Completo habla de lo que se deriva, no de lo que pertenece."]]]},
 {id:"k11",k:"seq",t:"compacidad",ex:"Γ es consistente si y solo si todo subconjunto FINITO de Γ es consistente (ejercicio 4). La razón: una derivación usa finitas hipótesis. Uso: para ver que un conjunto infinito es inconsistente, alcanza con encontrar un pedazo finito inconsistente.",p:"Verificá que se entendió.",mo:1,sl:["en {pi → pi+1 : i ∈ ℕ} ∪ {p0, ¬p5}, para ver que es inconsistente alcanza con",["{p0, p0 → p1, …, p4 → p5, ¬p5}","Un pedazo finito que deriva ⊥.","qué alcanza",["revisar las infinitas fórmulas","Por compacidad alcanza con un pedazo finito."]]]}]);

lgEx("Teórico · completitud (predicados)","lg4",["m:Teórico · consistencia (PROP):ej"],["Conceptos del teórico (12_PredComp)"],[
 {id:"q1",k:"seq",t:"lo mismo en predicados",ex:"En predicados todo se traslada cambiando «valuación» por «estructura»: Γ ⊨ φ si toda estructura que modela Γ modela φ; corrección y completitud valen igual; y Γ es consistente si y solo si tiene un modelo. Para mostrar φ ∉ Cons(Γ): una estructura que modele Γ donde φ falle.",p:"Verificá que se entendió.",sl:["para mostrar que Γ es consistente das",["una estructura que modele Γ","Condición suficiente de consistencia.","qué das",["una derivación de ⊥","Eso probaría que es inconsistente."]]]},
 {id:"q2",k:"seq",t:"Mod, Th y Cons",ex:"Γ es un conjunto de fórmulas. M ⊨ Γ («M modela Γ», M es modelo de Γ) quiere decir que TODAS las fórmulas de Γ son verdaderas en M. Mod(Γ): las estructuras que modelan todo Γ. Th(K): las sentencias verdaderas en todas las estructuras de K. Cons(Γ): lo que se deriva de Γ. Por corrección y completitud, Cons(Γ) = Th(Mod(Γ)). Th({M}) (lo verdadero en una sola estructura) es consistente maximal: el «{φ | v(φ) = 1}» de predicados.",p:"Verificá que se entendió.",mo:1,sl:["M ⊨ Γ quiere decir",["toda fórmula de Γ es verdadera en M","«M modela Γ»: M hace verdaderas a todas (nota de Luca 23/11: no estaba segura la definición).","qué es modelar",["alguna fórmula de Γ es verdadera en M","Tienen que valer TODAS."],["Γ se deriva de M","M es una estructura: no se deriva nada de ella; ⊨ es verdad, ⊢ es derivación."]],"\n","Mod(Γ) es",
   ["el conjunto de las estructuras M con M ⊨ Γ","Los modelos de Γ.","Mod",["el conjunto de las fórmulas verdaderas en M","Eso es Th({M})."]],"\n","Cons(Γ) ⊆ Th(Mod(Γ)) sale de",["corrección","Lo derivado vale en todo modelo de Γ.","la inclusión",["completitud","Completitud da la otra inclusión."]],"\n","para ver que Cons(Γ) NO es maximal, sirve",
   ["Cons(Γ) ⊊ Th({M}) para un modelo M de Γ","Un consistente que lo contiene estrictamente.","qué sirve",["Cons(Γ) ⊆ Th({M})","Podrían ser iguales: hace falta que sea estricta."]]]}]);

/* ===== PRÁCTICO 5 (22/11): ejercicios desarmados en la sucesión de pensamientos. Previa: los conceptos. ===== */
const P5=["m:Teórico · consistencia (PROP):ej"];
lgEx("P5 · Ej. 1 (¿consistente?)","lg4",P5,["Práctico 5 · Ejercicio 1","Determine cuáles de los siguientes conjuntos son consistentes y cuáles no. Justifique.","a. {¬p1 ∧ p2 → p0, p1 → (¬p0 → p2), p0 ↔ ¬p2}","b. {p0 → p1, p1 → p2, p2 → p3, p3 → ¬p0}","c. {p0, p1, p1 → ¬p0}","d. {p0 → p1, p0 ∧ p2 → p1 ∧ p3, p0 ∧ p2 ∧ p4 → p1 ∧ p3 ∧ p5, . . .}","e. {p0, ¬p1 ∧ p2, p1 → ¬p2}"],[
 {id:"a",k:"seq",t:"a) qué obliga y qué no",p:"Paso 1: ¿hay fórmulas que obliguen un valor? Mirá p0 ↔ ¬p2.",sl:["p0 ↔ ¬p2 obliga",["a que p0 y p2 tengan valores distintos","↔ pide que los dos lados valgan lo mismo: v(p0) = 1 − v(p2).","qué obliga",["a que p0 y p2 valgan 1","Con los dos en 1, ¬p2 vale 0 y el ↔ queda 1 ↔ 0."]],"\n","pruebo",
   ["v(p0) = 1, v(p2) = 0 y v(p1) = 0","Cumple el ↔; ¬p1 ∧ p2 vale 0 (la primera → da 1) y p1 → … empieza en 0.","la valuación",["todas en 0","p0 ↔ ¬p2 queda 0 ↔ 1 = 0."]],"\n","conclusión:",["consistente (condición suficiente)","Una valuación las hace 1 a todas.","el veredicto",["inconsistente","Encontraste una valuación que las satisface."]]]},
 {id:"b",k:"seq",t:"b) cuando nada obliga",p:"Paso 1 de b: todas son →. ¿Qué probás?",mo:1,sl:["una → vale 1 si",["el antecedente vale 0 (o el consecuente vale 1)","Por eso las → no obligan nada por sí solas.","cuándo vale 1",["los dos lados valen 1","También vale 1 con el antecedente en 0."]],"\n","pruebo",
   ["todas en 0: cada → empieza en 0","p3 → ¬p0 queda 0 → 1 = 1.","la valuación",["todas en 1","p3 → ¬p0 queda 1 → 0 = 0."]],"\n","conclusión:",["consistente","Todo en 0 las satisface.","el veredicto",["inconsistente","Hay una valuación que las satisface."]]]},
 {id:"c",k:"seq",t:"c) cuando algo choca",p:"Paso 1 de c: empezá por lo que obliga.",mo:1,sl:["p0 y p1 obligan",["v(p0) = 1 y v(p1) = 1","Una letra sola en el conjunto tiene que valer 1.","qué obligan",["nada: son letras","Si p0 ∈ Γ, cualquier valuación que satisfaga Γ hace 1 a p0."]],"\n","entonces p1 → ¬p0 vale",
   ["1 → 0 = 0","No hay elección: el conjunto es inconsistente.","el valor",["1","¬p0 vale 0."]],"\n","se muestra derivando ⊥:",["E→ con p1 y p1 → ¬p0 da ¬p0; E¬ con p0 y ¬p0 da ⊥","Así queda Γ ⊢ ⊥.","la derivación",["E¬ con p1 y p1 → ¬p0","E¬ pide una fórmula y su negación: p0 y ¬p0."]]]},
 {id:"d",k:"seq",t:"d) un conjunto infinito",p:"d es infinito. ¿Cambia algo?",mo:1,sl:["que sea infinito",["no cambia el método: busco una valuación que haga 1 a todas","La condición suficiente vale para cualquier Γ.","qué cambia",["obliga a usar compacidad","Compacidad sirve, pero acá alcanza con una valuación."]],"\n","pruebo",
   ["todas en 0: cada antecedente (p0, p0 ∧ p2, …) vale 0","Todas las → valen 1. (Todas en 1 también sirve: los consecuentes valen 1.)","la valuación",["v(p0) = 1 y el resto en 0","p0 → p1 queda 1 → 0 = 0."]],"\n","conclusión:",["consistente","Una valuación las satisface.","el veredicto",["inconsistente","Hay una valuación que las satisface."]]]},
 {id:"e",k:"seq",t:"e) lo que obliga decide todo",p:"Paso 1 de e: empezá por lo que obliga.",mo:1,sl:["p0 y ¬p1 ∧ p2 obligan",["v(p0) = 1, v(p1) = 0, v(p2) = 1","El ∧ obliga a los dos lados.","qué obligan",["v(p0) = 1 y nada más","¬p1 ∧ p2 también obliga: p1 en 0 y p2 en 1."]],"\n","entonces p1 → ¬p2 vale",
   ["0 → 0 = 1","El antecedente p1 vale 0.","el valor",["1 → 0 = 0","v(p1) = 0, no 1."]],"\n","conclusión:",["consistente","Esa valuación satisface a las tres.","el veredicto",["inconsistente","No hubo choque."]]]}]);
lgEx("P5 · Ej. 2d (unión e intersección)","lg4",P5,["Práctico 5 · Ejercicio 2 d","Para cada una de las siguientes afirmaciones indique si es verdadera o falsa, justificando en cada caso.","I. Para todo Γ y ∆ subconjuntos consistentes de PROP, Γ ∪ ∆ es consistente.","II. Para todo Γ y ∆ subconjuntos de PROP, si Γ es consistente y ∆ es inconsistente, entonces Γ ∩ ∆ es consistente."],[
 {id:"i",k:"seq",t:"I. la unión",p:"Paso 1: pensá dos conjuntos consistentes que se contradigan ENTRE ELLOS.",sl:["Γ ∪ ∆ puede fallar si",["Γ y ∆ obligan valores opuestos","Cada uno solo está bien; juntos chocan.","la idea",["Γ o ∆ es inconsistente","La letra dice que los dos son consistentes."]],"\n","contraejemplo:",
   ["Γ = {p0} y ∆ = {¬p0}","Cada uno tiene una valuación; la unión tiene p0 y ¬p0.","el contraejemplo",["Γ = {p0} y ∆ = {p1}","{p0, p1} es consistente: no refuta nada."]],"\n","I es",["FALSA","Un «para todo» falso se refuta con un contraejemplo.","el veredicto",["VERDADERA","{p0} ∪ {¬p0} es inconsistente."]]]},
 {id:"ii",k:"seq",t:"II. la intersección",p:"Paso 1 de II: ¿qué relación hay entre Γ ∩ ∆ y Γ?",mo:1,sl:["Γ ∩ ∆",["está incluido en Γ","Lo que está en los dos está, en particular, en Γ.","la relación",["está incluido en ∆, así que es inconsistente","Un subconjunto de un inconsistente puede ser consistente (por ejemplo ∅)."]],"\n","un subconjunto de un consistente es",
   ["consistente: la valuación que satisface a Γ satisface a cualquier parte de Γ","Condición suficiente.","por qué",["a veces inconsistente","Si Γ ∩ ∆ ⊢ ⊥, también Γ ⊢ ⊥ (más hipótesis no estorban)."]],"\n","II es",["VERDADERA","Γ ∩ ∆ ⊆ Γ y Γ es consistente.","el veredicto",["FALSA","No hay contraejemplo: siempre queda dentro de Γ."]]]}]);

lgEx("P5 · Ej. 6 (completo)","lg4",P5,["Práctico 5 · Ejercicio 6","Un conjunto Γ es completo si y sólo si es consistente y para toda φ ∈ PROP se cumple que: Γ ⊢ φ o Γ ⊢ ¬φ.","a. Demuestre que el conjunto {p0, p1} no es completo.","b. Demuestre que el conjunto P = {p0, p1, p2, . . . , pn, . . .} es completo.","c. De un conjunto R, R ⊆ PROP, R ∩ P = ∅ tal que R es completo."],[
 {id:"a",k:"seq",t:"a) {p0, p1} no es completo",p:"Paso 1: ¿qué hay que mostrar y con qué fórmula?",sl:["no completo: alcanza con",["una φ que Γ no decide: Γ ⊬ φ y Γ ⊬ ¬φ","Falla «para toda φ, Γ ⊢ φ o Γ ⊢ ¬φ».","qué alcanza",["que Γ sea inconsistente","{p0, p1} es consistente; lo que falla es la otra mitad."]],"\n","φ :=",
   ["p2","No aparece en Γ: Γ no dice nada de ella.","la fórmula",["p0","Γ ⊢ p0."],["¬p1","Γ ⊢ p1, así que Γ ⊢ ¬¬p1: Γ sí decide ¬p1."]],"\n","se muestra con",
   ["v (todo en 1) y w (p0 = p1 = 1, p2 = 0): las dos satisfacen Γ; por corrección Γ ⊬ ¬p2 (v) y Γ ⊬ p2 (w)","Dos valuaciones que satisfacen Γ y no coinciden en p2.","la justificación",["p2 ∉ Γ","No pertenecer no alcanza: hay que ver que no se deriva."]]]},
 {id:"b",k:"seq",t:"b) P es completo",p:"Paso 1 de b: ¿qué camino conviene?",mo:1,sl:["camino:",["una única valuación que satisface P (caracterización semántica)","Reduce todo a valuaciones.","el camino",["derivar cada φ o su negación","Habría que hacerlo para infinitas φ."]],"\n","existe:",
   ["v con v(pi) = 1 para todo i","Hace 1 a cada letra de P.","la existencia",["v con todo en 0","v(p0) = 0: no satisface P."]],"\n","es única porque",
   ["cada pi ∈ P obliga a w(pi) = 1, y una valuación queda fijada por sus letras","Cualquier w que satisfaga P es v.","la unicidad",["P es infinito","Lo que importa es que fija TODAS las letras."]]]},
 {id:"c",k:"seq",t:"c) un completo sin letras",p:"Paso 1 de c: R no puede tener letras sueltas. ¿Cómo fija cada letra?",mo:1,sl:["R tiene que",["fijar el valor de cada letra sin usar pi sola","Completo = una única valuación.","qué tiene que hacer",["tener solo tautologías","Las tautologías no fijan nada: valen en toda valuación."]],"\n","R :=",
   ["{¬pi : i ∈ ℕ}","Cada ¬pi obliga a pi = 0: la única valuación es todo en 0. (También {¬¬pi} sirve.)","el conjunto",["{¬p0}","Las otras letras quedan libres."],["{¬⊥}","No fija ninguna letra."]]]}]);

lgEx("P5 · Ej. 8b (teorías)","lg4",P5,["Práctico 5 · Ejercicio 8","Un conjunto Γ es una teoría si y sólo si Cons(Γ) ⊆ Γ.","b. Indique cuáles de las siguientes afirmaciones son correctas y cuáles no. Justifique su respuesta:","Si Γ es teoría entonces Γ es consistente.","Si Γ es teoría entonces Γ es inconsistente.","Si Γ es una teoría inconsistente entonces Γ = PROP.","Cons(Γ) es consistente si y sólo si Γ es consistente."],[
 {id:"b1",k:"seq",t:"teoría ⇒ consistente",p:"«Si Γ es teoría entonces Γ es consistente.» Buscá una teoría que no lo sea.",sl:["contraejemplo:",["PROP: es teoría (tiene todo) y es inconsistente","Cons(PROP) ⊆ PROP trivialmente, y PROP ∋ ⊥.","el contraejemplo",["Cons(∅)","Es teoría y SÍ es consistente: no refuta."]],"\n","la afirmación es",["FALSA","Hay una teoría inconsistente.","el veredicto",["VERDADERA","PROP es teoría e inconsistente."]]]},
 {id:"b2",k:"seq",t:"teoría ⇒ inconsistente",p:"«Si Γ es teoría entonces Γ es inconsistente.»",mo:1,sl:["contraejemplo:",["Cons(∅) (los teoremas): es teoría y es consistente","Cons de algo siempre es teoría; ∅ es consistente.","el contraejemplo",["PROP","PROP es inconsistente: no refuta."]],"\n","la afirmación es",["FALSA","Hay teorías consistentes.","el veredicto",["VERDADERA","Cons(∅) es una teoría consistente."]]]},
 {id:"b3",k:"seq",t:"teoría inconsistente ⇒ PROP",p:"«Si Γ es una teoría inconsistente entonces Γ = PROP.»",mo:1,sl:["Γ inconsistente ⇒",["Γ ⊢ φ para toda φ","Lema 1.6.3.","el primer paso",["Γ ⊢ ⊥ y nada más","De ⊥ sale todo con E⊥."]],"\n","y como es teoría,",
   ["toda φ está en Γ, o sea Γ = PROP","Teoría: lo que deriva está adentro.","el cierre",["Γ = {⊥}","{⊥} deriva todo y no lo contiene: no es teoría."]],"\n","la afirmación es",["VERDADERA","Las dos cosas juntas dan PROP.","el veredicto",["FALSA","Se probó para cualquier Γ."]]]},
 {id:"b4",k:"seq",t:"Cons(Γ) consistente ⇔ Γ consistente",p:"«Cons(Γ) es consistente si y sólo si Γ es consistente.»",mo:1,sl:["⇒: si Γ ⊢ ⊥, entonces",["⊥ ∈ Cons(Γ), así que Cons(Γ) es inconsistente","Contrarrecíproco.","la ida",["Cons(Γ) sigue siendo consistente","⊥ quedaría adentro."]],"\n","⇐: si Cons(Γ) ⊢ ⊥, entonces",
   ["Γ ⊢ ⊥: cada hipótesis de Cons(Γ) se deriva de Γ, y se pegan las derivaciones","Lo derivable de lo derivable es derivable.","la vuelta",["no se puede saber nada de Γ","Γ ⊆ Cons(Γ) y todo Cons(Γ) sale de Γ."]],"\n","la afirmación es",["VERDADERA","Valen las dos direcciones.","el veredicto",["FALSA","Las dos direcciones valen."]]]}]);

lgEx("P5 · Ej. 11b (independiente)","lg4",P5,["Práctico 5 · Ejercicio 11","Decimos que φ es independiente de Γ si Γ ⊬ φ y Γ ⊬ ¬φ.","b. Demuestre que p1 → p2 es independiente de {p1 ↔ p0 ∧ ¬p2, p2 → p0}"],[
 {id:"b1",k:"seq",t:"qué hay que mostrar",p:"Paso 1: ¿qué necesitás encontrar?",sl:["dos valuaciones que satisfacen Γ:",["una con p1 → p2 en 1 y otra con p1 → p2 en 0","Por corrección, ni ¬(p1 → p2) ni p1 → p2 se derivan.","qué busco",["una que satisfaga Γ y haga 1 a p1 → p2","Eso solo muestra Γ ⊬ ¬(p1 → p2): falta la otra."]]]},
 {id:"b2",k:"seq",t:"la que hace 0 a p1 → p2",p:"Paso 2: buscá w con w(p1 → p2) = 0 que satisfaga Γ.",mo:1,sl:["p1 → p2 vale 0 solo si",["p1 = 1 y p2 = 0","Es el único caso en que una → vale 0.","qué obliga",["p1 = 0","Con p1 = 0 la → vale 1."]],"\n","entonces p1 ↔ p0 ∧ ¬p2 obliga",
   ["p0 = 1 (1 ↔ p0 ∧ 1)","El lado derecho tiene que valer 1.","p0",["p0 = 0","Quedaría 1 ↔ 0."]],"\n","y p2 → p0 vale",["0 → 1 = 1: w satisface Γ","w(p0) = w(p1) = 1, w(p2) = 0.","la verificación",["1 → 1","w(p2) = 0."]]]},
 {id:"b3",k:"seq",t:"la que hace 1 a p1 → p2",p:"Paso 3: buscá v con v(p1 → p2) = 1 que satisfaga Γ. Probá lo más simple.",mo:1,sl:["pruebo",["todas en 0","p1 → p2 = 0 → 0 = 1; p1 ↔ p0 ∧ ¬p2 = 0 ↔ 0 = 1; p2 → p0 = 1.","la valuación",["todas en 1","p1 ↔ p0 ∧ ¬p2 queda 1 ↔ 0 = 0."]],"\n","conclusión:",["Γ ⊬ p1 → p2 (por w) y Γ ⊬ ¬(p1 → p2) (por v): es independiente","Corrección leída al revés, dos veces.","la conclusión",["Γ ⊢ p1 → p2 (por v)","Una valuación no prueba una derivación."]]]}]);

lgEx("P5 · Ej. 14 (teorías y maximales)","lg4",P5,["Práctico 5 · Ejercicio 14","Considere el siguiente conjunto Γ = {p0, p1}","a. Pruebe que ¬p2 ∉ Cons(Γ).","b. Defina una teoría T consistente que cumpla: Cons(Γ) ⊂ T, ¬p2 ∈ T, T no es consistente maximal. Justifique su respuesta.","c. Defina un conjunto consistente maximal ∆0 tal que T ⊂ ∆0.","d. Defina un conjunto consistente maximal ∆1 tal que Γ ⊂ ∆1 pero T ⊄ ∆1.","e. Determine si las siguientes afirmaciones son verdaderas. I. ∆0 ∪ ∆1 es teoría. II. ∆0 ∪ ∆1 es consistente. Justifique su respuesta."],[
 {id:"a",k:"seq",t:"a) ¬p2 ∉ Cons(Γ)",p:"Paso 1: traducí y elegí el camino.",sl:["¬p2 ∉ Cons(Γ) ⇔",["Γ ⊬ ¬p2","Definición de Cons.","qué es",["¬p2 ∉ Γ","Cons son las consecuencias, no solo los elementos."]],"\n","se muestra con",
   ["una valuación que haga 1 a p0 y p1, y 0 a ¬p2: todas en 1 (corrección)","v(¬p2) = 0 con v satisfaciendo Γ.","la justificación",["todas en 0","No satisface Γ."]]]},
 {id:"b",k:"seq",t:"b) una teoría T",p:"Paso 1 de b: ¿cuál es la forma más simple de armar una teoría que contenga ciertas fórmulas?",mo:1,sl:["T :=",["Cons(Γ ∪ {¬p2}) = Cons({p0, p1, ¬p2})","Cons de algo siempre es teoría.","la teoría",["Γ ∪ {¬p2}","No es teoría: no tiene sus consecuencias (p0 ∧ p1, …)."]],"\n","es consistente porque",
   ["v(p0) = v(p1) = 1, v(p2) = 0 satisface {p0, p1, ¬p2}","Alcanza con UNA valuación: si v satisface todo, por corrección lo que se deriva también vale en v, y como v(⊥) = 0, ⊥ no se deriva (consistente ⇔ satisfacible). Y Cons de un consistente es consistente (8b).","la consistencia",["tiene a ¬p2","Eso no dice nada."],["hay que probar con todas las valuaciones","Eso es para ver que una fórmula es VÁLIDA (⊨ φ). Para consistencia alcanza con que EXISTA una valuación que satisfaga todo (nota de Luca 23/11)."]],"\n","Cons(Γ) ⊂ T estricto porque",["¬p2 ∈ T y ¬p2 ∉ Cons(Γ) (parte a)","Una fórmula de más.","la inclusión",["Γ ⊆ T","Eso da ⊆, no ⊂."]],"\n","no es maximal porque",
   ["p3 queda libre: ni p3 ni ¬p3 están en T","Dos valuaciones (p3 en 1 o en 0) satisfacen la base.","no maximal",["T es una teoría","Las teorías pueden ser maximales o no."]]]},
 {id:"c",k:"seq",t:"c) un maximal ∆0 que contiene a T",p:"Paso 1 de c: ¿cómo se arma un maximal?",mo:1,sl:["{φ | v(φ) = 1} es consistente maximal porque",["v lo satisface, y para cada φ está φ o está ¬φ: no se le puede agregar nada","Consistente: v satisface todo. Maximal: con φ o ¬φ adentro, agregar cualquier fórmula que falte mete una contradicción (nota de Luca 23/11).","por qué es maximal",["tiene todas las fórmulas","Tener todas lo haría inconsistente (estarían p y ¬p)."]],"\n","para que contenga a T = Cons({p0, p1, ¬p2}), v tiene que",
   ["hacer verdaderas p0, p1 y ¬p2: v(p0) = v(p1) = 1 y v(p2) = 0","Si v satisface la base, satisface todo T (corrección).","qué pide T",["hacer verdaderas todas las letras","Con v(p2) = 1, ¬p2 sería falsa y quedaría afuera."]],"\n","∆0 :=",["{φ | v(φ) = 1} con v(p0) = v(p1) = 1, v(p2) = 0 y el resto en 0","El maximal típico, con una v que satisfaga T.","el maximal",["{φ | v(φ) = 1} con todo en 1","v(¬p2) = 0: ¬p2 ∉ ∆0, así que T ⊄ ∆0."]]]},
 {id:"d",k:"seq",t:"d) un maximal ∆1 sin T",p:"Paso 1 de d: tiene que contener a Γ pero no a T.",mo:1,sl:["∆1 :=",["{φ | v(φ) = 1} con todo en 1","Tiene p0 y p1; como v(p2) = 1, ¬p2 ∉ ∆1, así que T ⊄ ∆1.","el maximal",["{φ | v(φ) = 1} con p0 = p1 = 1 y el resto en 0","v(¬p2) = 1: ¬p2 ∈ ∆1, y T ⊆ ∆1."]]]},
 {id:"e",k:"seq",t:"e) la unión",p:"Paso 1 de e: mirá p2 en ∆0 y en ∆1.",mo:1,sl:["en ∆0 ∪ ∆1 están",["¬p2 (de ∆0) y p2 (de ∆1)","Cada maximal decidió p2 distinto.","qué está",["solo ¬p2","∆1 tiene a p2."]],"\n","II. ∆0 ∪ ∆1 es consistente?",
   ["NO: deriva ⊥ con E¬","p2 y ¬p2 juntas.","II",["SÍ: es unión de consistentes","La unión de consistentes puede no serlo (ejercicio 2d)."]],"\n","I. ¿es teoría?",
   ["NO: deriva ⊥ y ⊥ ∉ ∆0 ∪ ∆1","Una teoría inconsistente sería PROP (ejercicio 8b), y ⊥ no está en ninguno.","I",["SÍ: es unión de teorías","La unión de teorías puede no ser teoría."]]]}]);
